import React from "react";
import Typewriter from "typewriter-effect";
import { greeting } from "../../portfolio";

function Type() {
  return (
    <Typewriter
      options={{
        strings: greeting.subTitle,
        autoStart: true,
        loop: true,
        deleteSpeed: 50,
        // The library splits with String.prototype.split(""), which cuts the
        // 🤖 / 💻 surrogate pairs in half and renders a � for one frame on
        // the way in and on the way out. Array.from is code-point aware.
        stringSplitter: (s) => Array.from(s),
      }}
    />
  );
}

export default Type;
